{
	"$schema": "https://schemas.wp.org/trunk/block.json",
	"apiVersion": 3,
	"name": "telex/block-site-word-counter",
	"version": "0.1.0",
	"title": "Site Word Counter",
	"category": "widgets",
	"icon": "analytics",
	"description": "Displays the total number of words published across your entire site",
	"example": {
		"attributes": {
			"enableAnimation": true
		}
	},
	"attributes": {
		"enableAnimation": {
			"type": "boolean",
			"default": true
		},
		"textAlignment": {
			"type": "string",
			"default": "left"
		}
	},
	"supports": {
		"html": false,
		"align": ["left", "center", "right", "wide", "full"],
		"color": {
			"background": false,
			"text": true,
			"gradients": false
		},
		"typography": {
			"fontSize": true,
			"fontFamily": true,
			"fontWeight": true
		},
		"spacing": {
			"padding": true,
			"margin": true
		}
	},
	"textdomain": "site-word-counter-block-wp",
	"editorScript": "file:./index.js",
	"editorStyle": "file:./index.css",
	"style": "file:./style-index.css",
	"viewScript": "file:./view.js",
	"render": "file:./render.php"
}

  /**
 * Registers a new block provided a unique name and an object defining its behavior.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/block-api/block-registration/
 */
import { registerBlockType } from '@wordpress/blocks';

/**
 * Lets webpack process CSS, SASS or SCSS files referenced in JavaScript files.
 * All files containing `style` keyword are bundled together. The code used
 * gets applied both to the front of your site and to the editor.
 *
 * @see https://www.npmjs.com/package/@wordpress/scripts#using-css
 */
import './style.scss';

/**
 * Internal dependencies
 */
import Edit from './edit';
import metadata from './block.json';

/**
 * Every block starts by registering a new block type definition.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/block-api/block-registration/
 */
registerBlockType( metadata.name, {
	/**
	 * @see ./edit.js
	 */
	edit: Edit,
} );

/**
 * Retrieves the translation of text.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/packages/packages-i18n/
 */
import { __ } from '@wordpress/i18n';

/**
 * React hook that is used to mark the block wrapper element.
 * It provides all the necessary props like the class name.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/packages/packages-block-editor/#useblockprops
 */
import { 
	useBlockProps,
	InspectorControls,
	BlockControls,
	AlignmentToolbar
} from '@wordpress/block-editor';

import {
	PanelBody,
	ToggleControl
} from '@wordpress/components';

import { useState, useEffect } from '@wordpress/element';
import apiFetch from '@wordpress/api-fetch';

/**
 * Lets webpack process CSS, SASS or SCSS files referenced in JavaScript files.
 * Those files can contain any CSS code that gets applied to the editor.
 *
 * @see https://www.npmjs.com/package/@wordpress/scripts#using-css
 */
import './editor.scss';

/**
 * The edit function describes the structure of your block in the context of the
 * editor. This represents what the editor will render when the block is used.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/block-api/block-edit-save/#edit
 *
 * @return {Element} Element to render.
 */
export default function Edit({ attributes, setAttributes }) {
	const { enableAnimation, textAlignment } = attributes;
	const [wordCount, setWordCount] = useState(null);
	const [isLoading, setIsLoading] = useState(true);

	const blockProps = useBlockProps({
		className: `has-text-align-${textAlignment}`,
		style: {
			textAlign: textAlignment
		}
	});

	// Fetch word count for preview
	useEffect(() => {
		const fetchWordCount = async () => {
			try {
				const response = await apiFetch({
					path: '/wp/v2/posts',
					method: 'GET',
					data: {
						status: 'publish',
						per_page: 100,
						context: 'edit'
					}
				});

				// This is a simplified calculation for the editor preview
				// The actual calculation happens server-side
				let totalWords = 0;
				response.forEach(post => {
					if (post.content && post.content.rendered) {
						const textContent = post.content.rendered.replace(/<[^>]*>/g, '');
						const words = textContent.trim().split(/\s+/);
						totalWords += words.length;
					}
				});

				setWordCount(totalWords);
				setIsLoading(false);
			} catch (error) {
				console.error('Error fetching word count:', error);
				setWordCount(0);
				setIsLoading(false);
			}
		};

		fetchWordCount();
	}, []);

	const formatNumber = (num) => {
		if (num === null) return '...';
		return new Intl.NumberFormat().format(num);
	};

	return (
		<>
			<BlockControls>
				<AlignmentToolbar
					value={textAlignment}
					onChange={(nextAlign) => {
						setAttributes({ textAlignment: nextAlign });
					}}
				/>
			</BlockControls>

			<InspectorControls>
				<PanelBody title={__('Word Counter Settings', 'site-word-counter-block-wp')}>
					<ToggleControl
						label={__('Enable number animation', 'site-word-counter-block-wp')}
						checked={enableAnimation}
						onChange={(value) => setAttributes({ enableAnimation: value })}
						help={__('Animate the number counting up when the page loads', 'site-word-counter-block-wp')}
					/>
				</PanelBody>
			</InspectorControls>

			<div {...blockProps}>
				<div className="wp-block-telex-site-word-counter">
					<span className="word-counter-number">
						{isLoading ? (
							<span className="word-counter-loading">
								{__('Calculating...', 'site-word-counter-block-wp')}
							</span>
						) : (
							formatNumber(wordCount)
						)}
					</span>
				</div>
			</div>
		</>
	);
}

/**
 * The following styles get applied both on the front of your site
 * and in the editor.
 *
 * Replace them with your own styles or remove the file completely.
 */

.wp-block-telex-site-word-counter {
	.word-counter-number {
		/* Use theme default font styles */
		font-family: inherit;
		font-size: inherit;
		font-weight: inherit;
		color: inherit;
		line-height: inherit;
		letter-spacing: inherit;
	}

	.word-counter-loading {
		opacity: 0.6;
		font-style: italic;
	}

	// Alignment classes
	&.has-text-align-left {
		text-align: left;
	}

	&.has-text-align-center {
		text-align: center;
	}

	&.has-text-align-right {
		text-align: right;
	}
}

/**
 * The following styles get applied inside the editor only.
 *
 * Replace them with your own styles or remove the file completely.
 */

.wp-block-telex-site-word-counter {
	.word-counter-loading {
		animation: pulse 1.5s ease-in-out infinite alternate;
	}
}

@keyframes pulse {
	from { opacity: 0.4; }
	to { opacity: 1; }
}

/**
 * Use this file for JavaScript code that you want to run in the front-end
 * on posts/pages that contain this block.
 *
 * When this file is defined as the value of the `viewScript` property
 * in `block.json` it will be enqueued on the front end of the site.
 *
 * @see https://developer.wordpress.org/block-editor/reference-guides/block-api/block-metadata/#view-script
 */

// Add number formatting animation on load
document.addEventListener('DOMContentLoaded', function() {
	const wordCounters = document.querySelectorAll('.wp-block-telex-site-word-counter');

	wordCounters.forEach(function(counterBlock) {
		// Check if animation is enabled
		const animationEnabled = !counterBlock.hasAttribute('data-no-animation');

		if (!animationEnabled) {
			return;
		}

		const numberElement = counterBlock.querySelector('.word-counter-number');
		if (!numberElement) return;

		const finalNumber = parseInt(numberElement.textContent.replace(/,/g, ''));
		if (!isNaN(finalNumber) && finalNumber > 0) {
			animateCounter(numberElement, 0, finalNumber, 2000);
		}
	});
});

function animateCounter(element, start, end, duration) {
	let startTimestamp = null;
	const step = (timestamp) => {
		if (!startTimestamp) startTimestamp = timestamp;
		const progress = Math.min((timestamp - startTimestamp) / duration, 1);
		const current = Math.floor(progress * (end - start) + start);
		element.textContent = new Intl.NumberFormat().format(current);
		if (progress < 1) {
			window.requestAnimationFrame(step);
		}
	};
	window.requestAnimationFrame(step);
}
